@use "./components-core/theming/themes.scss" as t;

/* 1. Declare the order of all layers in your application.
      'themes' is before 'dynamic', so dynamic styles can still override theme vars.
      'dynamic' is last, so it will override all other layers.
      IF YOU ARE CHANGING THE ORDER, MAKE SURE TO UPDATE THE ORDER IN NestedApp, too.
       */
@layer reset, base, components, themes, dynamic;

@layer base {
  /************************/
  /*    Normalization     */
  /************************/

  /* Normal box-sizing model */
  *,
  *::before,
  *::after {
    box-sizing: border-box;
  }

  /* Remove default margin */
  * {
    margin: 0;
  }

  /* Allow percentage-based heights in the application */
  html,
  body {
    height: 100%;
  }

  #root {
    min-height: 100%;
    height: 100%;
  }

  html {
    -webkit-text-size-adjust: 100%;
    tab-size: 4;
    line-height: 1.7;
  }

  body {
    margin: 0;
  }

  /* Create a root stacking context */
  #root,
  #__next {
    isolation: isolate;
  }

  //tailwind css preflight
  *,
  :before,
  :after {
    box-sizing: border-box;
    border: 0 solid #e5e7eb;
  }

  hr {
    color: inherit;
    border-top-width: 1px;
    height: 0;
  }

  abbr:where([title]) {
    -webkit-text-decoration: underline dotted;
    text-decoration: underline dotted;
  }

  h1,
  h2,
  h3,
  h4,
  h5,
  h6 {
    // font-size: inherit;
    font-weight: inherit;
  }

  a {
    color: inherit;
    -webkit-text-decoration: inherit;
    text-decoration: inherit;
  }

  b,
  strong {
    font-weight: bolder;
  }

  code,
  kbd,
  samp,
  pre {
    font-family:
      ui-monospace,
      SFMono-Regular,
      Menlo,
      Monaco,
      Consolas,
      Liberation Mono,
      Courier New,
      monospace;
    font-size: 1em;
  }

  small {
    font-size: 80%;
  }

  sub,
  sup {
    vertical-align: baseline;
    font-size: 75%;
    line-height: 0;
    position: relative;
  }

  sub {
    bottom: -0.5em;
  }

  sup {
    top: -0.5em;
  }

  table {
    text-indent: 0;
    border-color: inherit;
    border-collapse: collapse;
  }

  button,
  input,
  optgroup,
  select,
  textarea {
    font-feature-settings: inherit;
    font-variation-settings: inherit;
    font-family: inherit;
    font-size: 100%;
    font-weight: inherit;
    line-height: inherit;
    color: inherit;
    margin: 0;
    padding: 0;
  }

  button,
  select {
    text-transform: none;
  }

  button {
    -webkit-appearance: button;
    background-color: transparent;
    background-image: none;
  }

  [type="button"] {
    -webkit-appearance: button;
    background-color: transparent;
    background-image: none;
  }

  [type="reset"] {
    -webkit-appearance: button;
    background-color: transparent;
    background-image: none;
  }

  [type="submit"] {
    -webkit-appearance: button;
    background-color: transparent;
    background-image: none;
  }

  :-moz-focusring {
    outline: auto;
  }

  :-moz-ui-invalid {
    box-shadow: none;
  }

  *:focus-visible {
    outline: t.$focus-outline;
    outline-offset: t.$outlineOffset--focus;
  }

  progress {
    vertical-align: baseline;
  }

  ::-webkit-inner-spin-button {
    height: auto;
  }

  ::-webkit-outer-spin-button {
    height: auto;
  }

  [type="search"] {
    -webkit-appearance: textfield;
    outline-offset: -2px;
  }

  ::-webkit-search-decoration {
    -webkit-appearance: none;
  }

  ::-webkit-file-upload-button {
    -webkit-appearance: button;
    font: inherit;
  }

  summary {
    display: list-item;
  }

  blockquote,
  dl,
  dd,
  h1,
  h2,
  h3,
  h4,
  h5,
  h6,
  hr,
  figure,
  p,
  pre {
    margin: 0;
  }

  fieldset {
    margin: 0;
    padding: 0;
  }

  legend {
    padding: 0;
  }

  // ol, ul, menu {
  //   margin: 0;
  //   padding: 0;
  //   list-style: none
  // }

  dialog {
    padding: 0;
  }

  textarea {
    resize: vertical;
  }

  input::-ms-input-placeholder {
    opacity: 1;
    color: #9ca3af;
  }

  input::placeholder {
    opacity: 1;
    color: #9ca3af;
  }

  textarea::-ms-input-placeholder {
    opacity: 1;
    color: #9ca3af;
  }

  textarea::placeholder {
    opacity: 1;
    color: #9ca3af;
  }

  button,
  [role="button"] {
    cursor: pointer;
  }

  :disabled {
    cursor: default;
  }

  img,
  svg,
  video,
  canvas,
  audio,
  iframe,
  embed,
  object {
    vertical-align: middle;
    display: block;
  }

  img,
  video {
    max-width: 100%;
    height: auto;
  }

  [hidden] {
    display: none;
  }
}
