// --- CSS properties of a particular AutoComplete variant
@mixin variant($variantName) {
  $suffix: if($variantName != "", "--#{$variantName}", "");
  border-radius: createThemeVar("Input:borderRadius-#{$component}#{$suffix}");
  border-color: createThemeVar("Input:borderColor-#{$component}#{$suffix}");
  border-width: createThemeVar("Input:borderWidth-#{$component}#{$suffix}");
  border-style: createThemeVar("Input:borderStyle-#{$component}#{$suffix}");
  font-size: createThemeVar("Input:fontSize-#{$component}#{$suffix}");
  background-color: createThemeVar("Input:backgroundColor-#{$component}#{$suffix}");
  box-shadow: createThemeVar("Input:boxShadow-#{$component}#{$suffix}");
  color: createThemeVar("Input:textColor-#{$component}#{$suffix}");

  &:hover {
    border-color: createThemeVar("Input:borderColor-#{$component}#{$suffix}--hover");
    background-color: createThemeVar("Input:backgroundColor-#{$component}#{$suffix}--hover");
    box-shadow: createThemeVar("Input:boxShadow-#{$component}#{$suffix}--hover");
    color: createThemeVar("Input:textColor-#{$component}#{$suffix}--hover");
  }

  &::placeholder {
    color: createThemeVar("Input:textColor-placeholder-#{$component}#{$suffix}");
    font-size: createThemeVar("Input:fontSize-placeholder-#{$component}#{$suffix}");
  }
}

@layer components {
  .command {
    width: 100%;
    height: auto;
    overflow: visible;
    background-color: transparent;
  }

  .badgeListWrapper {
    outline: none;
    width: 100%;
    // Allow the wrapper to shrink under flex pressure so the truncation
    // logic ("+N more" chip) can fire instead of the content pushing past
    // the row width. `!important` is required because xmlui's layout-prop
    // system emits an inline `flex: 0 0 auto` for every `width` value that
    // would otherwise re-pin shrink to 0.
    flex-shrink: 1 !important;
    min-width: 0;
    height: auto;
    min-height: $minHeight-AutoComplete;
    line-height: normal;
    gap: t.$space-1;
    display: flex;
    flex-direction: row;
    flex-wrap: nowrap;
    align-items: center;
    // The list inside truncates with `+N more` once the container runs out
    // of horizontal space — anything that overflows visually is clipped.
    overflow: hidden;
    position: relative;
    @include t.paddingVars($themeVars, $component);

    @include variant("");

    &.error {
      @include variant("error");
    }

    &.warning {
      @include variant("warning");
    }

    &.valid {
      @include variant("success");
    }

    &.disabled {
      cursor: not-allowed;
      background-color: $backgroundColor-AutoComplete--disabled;
      color: $textColor-AutoComplete--disabled;
      border-color: $borderColor-AutoComplete--disabled;
    }

    &.focused {
      outline: none;

      &::after {
        inset: $outlineOffset-AutoComplete--focus;
        border-width: $outlineWidth-AutoComplete--focus;
        border-color: $outlineColor-AutoComplete--focus;
        border-style: $outlineStyle-AutoComplete--focus;
      }
    }

    &::after {
      content: "";
      position: absolute;
      inset: 0;
      border-radius: inherit;
      pointer-events: none;
    }
  }

  .badgeList {
    position: relative;
    align-items: center;
    display: flex;
    flex-wrap: nowrap;
    min-width: 0;
    gap: 0.25rem;
  }

  .inputWrapper {
    display: flex;
    align-items: center;
    // The input shrinks down to here when many badges occupy the trigger.
    // Keep it tight so the trigger doesn't push a single fitting badge into
    // a "+N more" chip prematurely. 60px still fits a usable caret + a few
    // characters of placeholder before ellipsis.
    min-width: 60px;
    flex: 1;
    gap: t.$space-1;
  }

  .ghostMeasurer {
    position: absolute;
    left: -9999px; // @rtl-intentional: off-screen ghost element for measurement, not directional
    top: -9999px;
    visibility: hidden;
    pointer-events: none;
    display: flex;
    flex-direction: row;
    flex-wrap: nowrap;
    gap: 0.25rem;
  }

  .badge {
    width: fit-content;
    height: fit-content;
    min-width: 0;
    padding: $paddingVertical-AutoComplete-badge $paddingHorizontal-AutoComplete-badge;
    border-radius: $borderRadius-AutoComplete-badge;
    transition:
      color 0.2s,
      background-color 0.2s;
    user-select: none;
    cursor: pointer;
    display: flex;
    gap: t.$space-1;
    justify-content: center;
    align-items: center;
    font-size: $fontSize-AutoComplete-badge;
    background-color: $backgroundColor-AutoComplete-badge;
    color: $textColor-AutoComplete-badge;

    &:hover {
      background-color: $backgroundColor-AutoComplete-badge--hover;
      color: $textColor-AutoComplete-badge--hover;
    }

    &:active {
      background-color: $backgroundColor-AutoComplete-badge--active;
      color: $textColor-AutoComplete-badge--active;
    }
  }

  .commandInput {
    width: 100%;
    background-color: transparent;
    outline: none;

    &:disabled {
      cursor: not-allowed;
    }

    &::placeholder {
      color: $textColor-placeholder-AutoComplete;
    }

    &:focus-within {
      outline: none;
    }
  }

  .actions {
    display: flex;
    align-items: center;
    flex-shrink: 0;
    gap: t.$space-1_5;
  }

  .action {
    cursor: pointer;

    &.disabled {
      cursor: not-allowed;
    }
  }

  .autoCompleteEmpty {
    display: flex;
    padding: 10px 0;
    justify-content: center;
    align-items: center;
    font-size: t.$fontSize;
    gap: t.$space-4;
    width: 100%;
  }

  .commandList {
    width: 100%;
    position: absolute;
    overflow: hidden;
    top: t.$space-1;
    outline: none;
    border-radius: $borderRadius-menu-AutoComplete;
    border: $borderWidth-menu-AutoComplete solid $borderColor-menu-AutoComplete;
    background-color: $backgroundColor-menu-AutoComplete;
    box-shadow: $boxShadow-menu-AutoComplete;
    animation: fade-in 0.3s ease-in-out;
  }

  .autoCompleteOption {
    @include t.paddingVars($themeVars, "item-#{$component}");
    display: flex;
    gap: t.$space-1;
    align-items: center;
    justify-content: space-between;
    cursor: pointer;
    transition: background-color 0.2s ease;
    background-color: $backgroundColor-item-AutoComplete;

    &[aria-selected="true"] {
      background-color: $backgroundColor-item-AutoComplete--active;
    }

    &:hover,
    &.highlighted {
      background-color: $backgroundColor-item-AutoComplete--hover;
    }

    &[aria-disabled="true"],
    &.disabledOption {
      pointer-events: none;
      cursor: not-allowed;
      color: $textColor-item-AutoComplete--disabled;
      font-style: italic;
    }
  }

  .groupHeader {
    padding-top: createThemeVar("paddingTop-groupHeader-#{$component}");
    padding-bottom: createThemeVar("paddingBottom-groupHeader-#{$component}");
    padding-inline-start: createThemeVar("paddingHorizontal-groupHeader-#{$component}");
    padding-inline-end: createThemeVar("paddingHorizontal-groupHeader-#{$component}");
    font-size: createThemeVar("fontSize-groupHeader-#{$component}");
    font-weight: createThemeVar("fontWeight-groupHeader-#{$component}");
    letter-spacing: createThemeVar("letterSpacing-groupHeader-#{$component}");
    text-transform: createThemeVar("textTransform-groupHeader-#{$component}");
    color: createThemeVar("textColor-groupHeader-#{$component}");
    pointer-events: none;
    user-select: none;
  }
}

// --- We export the theme variables to add them to the component renderer
:export {
  themeVars: t.json-stringify($themeVars);
}
