@use "../../components-core/theming/themes" as t;

// --- This code snippet is required to collect the theme variables used in this module
$themeVars: ();
@function createThemeVar($componentVariable) {
  $themeVars: t.appendThemeVar($themeVars, $componentVariable) !global;
  @return t.getThemeVar($themeVars, $componentVariable);
}

@mixin validationDisplayVariant($variantName) {
  &.#{$variantName} {
    background-color: createThemeVar("backgroundColor-ValidationDisplay-#{$variantName}");
  
    &::before {
      background-color: createThemeVar("color-accent-ValidationDisplay-#{$variantName}");
    }
  
    .heading {
      color: createThemeVar("textColor-ValidationDisplay-#{$variantName}");
      font-weight: bold;
    }
  }
}

@layer components {
  .summaryContainer {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;

    &:empty{
      display: none;
    }
  }

  .validationContainer {
    position: relative;
    padding-top: 0;
    padding-bottom: 0.5rem;
    padding-inline-start: 1rem;

    &::before {
      position: absolute;
      top: 0;
      inset-inline-start: 0;
      display: block;
      content: "";
      height: 100%;
      width: 2px;
    }

    ul {
      list-style-position: inside;
      padding-inline-start: 0;
    }

    li {
      padding-inline-start: 2rem;

      &::marker {
        font-size: 0.625em;
      }
    }
    .noMarker {
      list-style: none;
      padding-inline-start: 1.6rem;
      line-height: 1.6rem;
    }

    @include validationDisplayVariant("error");
    @include validationDisplayVariant("warning");
    @include validationDisplayVariant("info");
    @include validationDisplayVariant("valid");

    &.noCloseButton {
      padding-top: 0.5rem;
    }
  }

  .headerStack {
    gap: 0.5rem;
  }

  .entrySpan {
    display: inline-flex;
  }

  .entrySpanWithField {
    gap: 0.25rem;
  }
}

// --- We export the theme variables to add them to the component renderer
:export {
  themeVars: t.json-stringify($themeVars);
}
